// CharacterCreator material adapters. Keep vendor files syncable, but NEVER render with
// its process-global mutable skin/hair uniforms: every avatar/material owns its snapshot.
import * as CC from './vendor/cc/materials.js';

function cloneValue(value) {
  if (Array.isArray(value)) return value.map(cloneValue);
  if (value?.clone) return value.clone();
  return value;
}
export function cloneUniforms(uniforms) {
  return Object.fromEntries(Object.entries(uniforms).map(([key, u]) => [key, { value: cloneValue(u.value) }]));
}
function isolate(material, globals) {
  const uniforms = cloneUniforms(globals), compile = material.onBeforeCompile;
  // Texture.clone shares image data but has independent GPU ownership.
  for (const u of Object.values(uniforms)) if (u.value?.isTexture) u.value.needsUpdate = true;
  material.userData.pluginUniforms = uniforms;
  material.onBeforeCompile = (shader, renderer) => {
    compile.call(material, shader, renderer);
    Object.assign(shader.uniforms, uniforms);
  };
  return material;
}
export function upgradeSkin(material, regions) {
  const upgraded = isolate(CC.upgradeSkin(material, regions), CC.skinUniforms);
  // Do not let the vendor singleton retain the last actor's regions texture.
  CC.skinUniforms.ccRegions.value = null; CC.skinUniforms.ccHasRegions.value = 0;
  return upgraded;
}
export const upgradeHair = (material, geometry) => isolate(CC.upgradeHair(material, geometry), CC.hairUniforms);
export function upgradeCornea(material) { CC.upgradeCornea(material); return isolate(material, CC.eyeUniforms); }
export function setSkinParams(parts, gender) {
  for (const mesh of parts) for (const mat of [].concat(mesh.material || [])) {
    const u = mat.userData?.pluginUniforms;
    if (u?.ccAreola) u.ccAreola.value = CC.areolaStrength(gender);
  }
}
export function createHairCollider(mesh) {
  const collider = CC.createHairCollider(mesh);
  return {
    ...collider,
    update() {
      // Vendor collider writes its globals synchronously; capture immediately, before another
      // entity ticks. Shader closures reference only the owned uniforms above.
      collider.update();
      for (const mat of [].concat(mesh.material || [])) {
        const own = mat.userData?.pluginUniforms;
        if (!own?.ccCollide) continue;
        own.ccCollide.value = 1;
        for (const key of ['ccCollideFrom', 'ccCollideTo', 'ccCapA', 'ccCapB', 'ccCapR']) {
          const value = CC.hairUniforms[key].value;
          if (Array.isArray(value)) value.forEach((v, i) => {
            if (own[key].value[i]?.copy) own[key].value[i].copy(v);
            else own[key].value[i] = v;
          });
          else own[key].value = value;
        }
      }
    },
  };
}
